"""1318 (#11, locomotion completion): Record-Coverage-v1287.ps1 with the locomotion cases the movement checklist still
lacks on the current build (candidate 1214cf, bank 1266), each filmed from the peer's free camera and checked from the
partner's own presentation state (coop-status.json.movement.json on the observer):
- walk8: half-stick walks in 8 directions; the partner's dominant direction sector (a/b by mix) must cover 8 sectors;
- crouch8: crouch, full-stick crouch walks in 8 directions, stand; crouched (stanceMix > .5) sectors must cover 8;
- sprint3: sprint forward, forward-left and forward-right (LeftThumb), with stops; sprintMix > .5 in each segment;
  each segment starts from the open spot, turned so the path runs along the room (take 1318a hit the wall);
- turns: in-place turns left and right of three sizes (full stick for the largest), standing then crouched; the
  partner's turn clips must cover 45, 90 and 180 degree variants in both directions;
- startstop: walk, run and sprint starts and stops and a walk-run-sprint speed ramp, each from the open spot (the
  source is re-placed while stopped; take 1318a ran into the wall); each stop settles (moving, then speed < .05)
  and run and sprint mixes engage;
- a deliberate re-placement is a teleport, which the partner presentation fades through by design; weight samples in
  the 1.2 s after one are not counted as drops (take 1318b counted them);
- stairs: up and down the Dunwall safe-room staircase; terrain weight engages with positive and negative grade.
Generated by make_coverage_v1318.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Record-Coverage-v1287.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:90])
    s = s.replace(old, new)

rep("[string]$Take='coverage-v1287a',[string]$Candidate='candidate-npc-combat-v1214av',[string[]]$Sources=@('host','client'),[string[]]$Cases=@('mana')",
    "[string]$Take='coverage-v1318c',[string]$Candidate='candidate-npc-combat-v1214cf',[string[]]$Sources=@('host','client'),[string[]]$Cases=@('walk8','crouch8','sprint3','turns','startstop','stairs')")
rep("# 1287 (#11): 'mana'", "# 1318 (#11, locomotion completion): walk8, crouch8, sprint3, turns, startstop and stairs on the current build, checked\n# from the partner's presentation state on the observer. Generated by make_coverage_v1318.py.\n# 1287 (#11): 'mana'")
# pwsh -File passes "-Cases a,b" as one string (take 1321b ran one case named "jumps,runjump,..."): split it, and
# refuse anything that is still not a plain case name.
rep("""$ErrorActionPreference='Stop';$root=""", """$Cases=@($Cases|ForEach-Object {$_-split','}|Where-Object {$_});if(@($Cases|Where-Object {$_-notmatch'^[a-z0-9]+$'}).Count){throw "Bad case list: $($Cases-join ' | ')"};$ErrorActionPreference='Stop';$root=""")
# The checkpoint reload can still be settling when the restored inventory is read (take 1321c: "Native inventory read
# failed" after host-fall); retry the read for up to 5 s.
rep("""foreach($r in 'host','client'){$restored=Q $r '--player-inventory'""", """foreach($r in 'host','client'){$restored=$null;for($ra=0;$ra-lt25-and!$restored;$ra++){try{$restored=Q $r '--player-inventory'}catch{Start-Sleep -Milliseconds 200}};if(!$restored){throw "Native inventory read failed after restore ($r)"}""")
# Per-case recording length.
rep("""   $samples=[Collections.Generic.List[object]]::new();$watch=[Diagnostics.Stopwatch]::StartNew();$step=0""",
    """   $samples=[Collections.Generic.List[object]]::new();$watch=[Diagnostics.Stopwatch]::StartNew();$step=0;$segments=[Collections.Generic.List[object]]::new();$placed=$false;$teleports=[Collections.Generic.List[double]]::new()""")
rep("""   while($watch.ElapsedMilliseconds-lt9500){""", """   while($watch.ElapsedMilliseconds-lt$caseMs){""")
# A deliberate re-placement is a teleport: the partner presentation fades through it by design (take 1318b counted it).
rep("""   $low=@($samples|Where-Object {$_.weight-lt.9});$row.lowWeightSamples=$low.Count""",
    """   $tp=@($teleports);$low=@($samples|Where-Object {$x=$_;$_.weight-lt.9-and!@($tp|Where-Object {$x.ms-ge$_-and$x.ms-lt$_+1200}).Count});$row.lowWeightSamples=$low.Count;$row.teleports=$tp""")
# Recording length follows the case length.
rep("""'-t','11','-an'""", """'-t',[string][Math]::Ceiling($caseMs/1000+2),'-an'""")
rep("""   $live=WaitLive "$key-placed" 20000;if(!$live.ok){throw 'Partner presentation not live after placement'}""",
    """   $caseMs=@{walk8=11500;crouch8=13800;sprint3=11000;turns=23500;startstop=17500;stairs=17500}[$case];if(!$caseMs){$caseMs=9500}
   $live=WaitLive "$key-placed" 20000;if(!$live.ok){throw 'Partner presentation not live after placement'}""")
# Placement: stairs at the safe-room staircase with the free camera beside it; the other new cases use the open lab spot.
rep("""   }elseif($case-in'crouchheavy','mana'){$inv=[Globalization.CultureInfo]::InvariantCulture""",
    """   }elseif($case-eq'stairs'){$inv=[Globalization.CultureInfo]::InvariantCulture
    C $source 'setviewpos -45.3 -179 65.1 0 0';Start-Sleep -Milliseconds 600
    $op=(Q $peer '--player').candidatePosition
    C $peer ('setviewpos {0} {1} {2} 325 0' -f ([double]$op[0]).ToString('F4',$inv),([double]$op[1]).ToString('F4',$inv),([double]$op[2]+1.7).ToString('F3',$inv));Start-Sleep -Milliseconds 400
    & "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $peer -Pitch 12 -Quick|Out-Null
    C $peer 'coop_observer_camera hold_at -47.6 -175.9 67.4';Start-Sleep -Milliseconds 500
    $cam=S $peer '.observer-camera.json';Save "$out/$key-observer-camera.json" $cam;if(!$cam.active){throw "Free camera not held: $($cam.result)"};$row.camera=@(-47.6,-175.9,67.4)
   }elseif($case-in'crouchheavy','mana'){$inv=[Globalization.CultureInfo]::InvariantCulture""")
rep("""   if($case-notin'kick','crouchheavy','note','mana'){& "$PSScriptRoot/Set-ObserverPitch.ps1\"""",
    """   if($case-notin'kick','crouchheavy','note','mana','stairs'){& "$PSScriptRoot/Set-ObserverPitch.ps1\"""")
# Inputs.
rep("""    if($case-eq'mana'){
     if($step-eq0-and$t-ge800){C $source 'coop_grant_item mana';$step=1}""",
    """    $walkDirs=@(@(0,13000),@(0,-13000),@(-13000,0),@(13000,0),@(-9200,9200),@(9200,-9200),@(9200,9200),@(-9200,-9200))
    if($case-eq'walk8'-and$step-lt8-and$t-ge1000+$step*1200){$d=$walkDirs[$step];& "$lab/Send-D2Input.ps1" -Role $source -DurationMs 900 -LeftX $d[0] -LeftY $d[1]|Out-Null;$segments.Add(@{ms=$t;dir=$step});$step++}
    if($case-eq'crouch8'){
     if($step-eq0-and$t-ge500){I $source B 180;$step=1}
     elseif($step-ge1-and$step-le8-and$t-ge1500+($step-1)*1300){$d=$runs[$step-1];& "$lab/Send-D2Input.ps1" -Role $source -DurationMs 1000 -LeftX $d[0] -LeftY $d[1]|Out-Null;$segments.Add(@{ms=$t;dir=$step-1});$step++}
     elseif($step-eq9-and$t-ge12600){I $source B 180;$step=10}}
    if($case-eq'sprint3'){$spr=@(@(0,32767,0),@(-23170,23170,315),@(23170,23170,45))
     if($step-gt0-and$step-lt3-and$t-ge200+$step*3200-and!$placed){C $source ('setviewpos -35 -153 68.1 {0} 0' -f $spr[$step][2]);$teleports.Add($t);$placed=$true}
     if($step-lt3-and$t-ge800+$step*3200){$d=$spr[$step];& "$lab/Send-D2Input.ps1" -Role $source -Button LeftThumb -DurationMs 1100 -LeftX $d[0] -LeftY $d[1]|Out-Null;$segments.Add(@{ms=$t;sprint=$step});$step++;$placed=$false}}
    if($case-eq'turns'){$tn=@(@(-22000,300),@(22000,300),@(-22000,650),@(22000,650),@(-32767,1500),@(32767,1500))
     if($step-lt6-and$t-ge800+$step*2000){$d=$tn[$step];& "$lab/Send-D2Input.ps1" -Role $source -RightX $d[0] -DurationMs $d[1]|Out-Null;$segments.Add(@{ms=$t;turn=$d});$step++}
     elseif($step-eq6-and$t-ge12800){I $source B 180;$step=7}
     elseif($step-ge7-and$step-lt11-and$t-ge13600+($step-7)*2200){$d=$tn[$step-5];& "$lab/Send-D2Input.ps1" -Role $source -RightX $d[0] -DurationMs $d[1]|Out-Null;$segments.Add(@{ms=$t;crouchedTurn=$d});$step++}
     elseif($step-eq11-and$t-ge22600){I $source B 180;$step=12}}
    if($case-eq'startstop'){$ss=@(@(800,14000,1200,'Neutral',0),@(3600,32767,1000,'Neutral',1),@(6400,32767,700,'LeftThumb',1),@(9400,9000,500,'Neutral',1),@(9900,32767,400,'Neutral',0),@(10300,32767,500,'LeftThumb',0),@(13600,-14000,1000,'Neutral',0))
     if($step-lt$ss.Count-and$t-ge$ss[$step][0]-600-and$ss[$step][4]-and!$placed){C $source 'setviewpos -35 -153 68.1 0 0';$teleports.Add($t);$placed=$true}
     if($step-lt$ss.Count-and$t-ge$ss[$step][0]){$d=$ss[$step];& "$lab/Send-D2Input.ps1" -Role $source -Button $d[3] -DurationMs $d[2] -LeftY $d[1]|Out-Null;$segments.Add(@{ms=$t;start=$step});$step++;$placed=$false}}
    if($case-eq'stairs'){
     if($step-eq0-and$t-ge800){& "$lab/Send-D2Input.ps1" -Role $source -DurationMs 6000 -LeftY 14000|Out-Null;$segments.Add(@{ms=$t;stairs='up'});$step=1}
     elseif($step-eq1-and$t-ge8000){C $source 'setviewpos -37.5 -179 68.1 180 0';$step=2}
     elseif($step-eq2-and$t-ge9400){& "$lab/Send-D2Input.ps1" -Role $source -DurationMs 6000 -LeftY 14000|Out-Null;$segments.Add(@{ms=$t;stairs='down'});$step=3}}
    if($case-eq'mana'){
     if($step-eq0-and$t-ge800){C $source 'coop_grant_item mana';$step=1}""")
# Samples gain the locomotion fields of the observer's presentation.
rep("""$samples.Add([pscustomobject]@{ms=$t;stance=$player.stance;""",
    """$samples.Add([pscustomobject]@{ms=$t;a=$mv.a;b=$mv.b;mix=$mv.mix;speed=$mv.speed;runMix=$mv.runMix;stanceMix=$mv.stanceMix;sprintMix=$mv.sprintMix;sprintSide=$mv.sprintSide;turnWeight=$mv.turnWeight;turnClip=$mv.turnClip;turnSerial=$mv.turnSerial;terrainWeight=$mv.terrainWeight;terrainGrade=$mv.terrainGrade;stance=$player.stance;""")
# Checks.
rep("""   if($case-eq'slide'){if(!@($samples|Where-Object {$_.slideWeight-gt.8}).Count){throw 'Partner slide not presented'};$row.checks.Add('Partner slide presented')}""",
    """   if($case-eq'slide'){if(!@($samples|Where-Object {$_.slideWeight-gt.8}).Count){throw 'Partner slide not presented'};$row.checks.Add('Partner slide presented')}
   Save "$out/$key-segments.json" @($segments)
   function Sector($x){if([double]$x.mix-lt.5){[int]$x.a}else{[int]$x.b}}
   if($case-in'walk8','crouch8'){
    $moving=@($samples|Where-Object {[double]$_.speed-gt.15-and[double]$_.weight-gt.9-and($case-ne'crouch8'-or[double]$_.stanceMix-gt.5)})
    $row.sectors=@($moving|ForEach-Object {Sector $_}|Sort-Object -Unique);$row.movingSamples=$moving.Count
    if(@($row.sectors).Count-lt8){throw "Partner direction sectors $(@($row.sectors)-join ',') (8 required)"};$row.checks.Add("Partner presented all 8 direction sectors ($case, $($moving.Count) samples)")
    if($case-eq'walk8'-and@($moving|Where-Object {[double]$_.runMix-gt.5}).Count-gt[Math]::Ceiling($moving.Count/5)){throw 'Walk presented as run'};if($case-eq'walk8'){$row.checks.Add('Half-stick walks stayed in the walk gait')}}
   if($case-eq'sprint3'){$row.sprintSegments=@();foreach($g in $segments){$hit=@($samples|Where-Object {$_.ms-ge$g.ms-and$_.ms-lt$g.ms+1800-and[double]$_.sprintMix-gt.5});$row.sprintSegments+=$hit.Count;if(!$hit.Count){throw "Sprint segment $($g.sprint) not presented"}}
    $row.sprintSides=@($samples|Where-Object {[double]$_.sprintMix-gt.5}|ForEach-Object {$_.sprintSide}|Sort-Object -Unique);$row.checks.Add("Sprint presented in all 3 segments (sides $(@($row.sprintSides)-join ','))")}
   if($case-eq'turns'){$tc=@($samples|Where-Object {[double]$_.turnWeight-gt.5}|ForEach-Object {[int]$_.turnClip}|Sort-Object -Unique);$row.turnClips=$tc
    $kinds=@($tc|ForEach-Object {$o=($_-149)%6;@('45','45','90','90','180','180')[$o]+@('L','R')[$o%2]}|Sort-Object -Unique);$row.turnKinds=$kinds
    $row.turnSerials=@($samples|ForEach-Object {$_.turnSerial}|Sort-Object -Unique).Count
    if($kinds.Count-lt6){throw "Partner turn variants $($kinds-join ',') (45, 90 and 180 left and right required)"};$row.checks.Add("Partner turn variants $($kinds-join ',')")}
   if($case-eq'startstop'){$stops=0;$moving=$false;foreach($x in $samples){if([double]$x.speed-gt.2){$moving=$true}elseif($moving-and[double]$x.speed-lt.05){$stops++;$moving=$false}};$row.stops=$stops
    $run=@($samples|Where-Object {[double]$_.runMix-gt.5}).Count;$spr=@($samples|Where-Object {[double]$_.sprintMix-gt.5}).Count;$row.runSamples=$run;$row.sprintSamples=$spr
    if($stops-lt4-or!$run-or!$spr){throw "Starts/stops incomplete (stops $stops, run $run, sprint $spr)"};$row.checks.Add("Partner settled $stops stops; run and sprint engaged")}
   if($case-eq'stairs'){C $peer 'coop_observer_camera off'
    $up=@($samples|Where-Object {[double]$_.terrainWeight-gt.5-and[double]$_.terrainGrade-gt.05}).Count;$dn=@($samples|Where-Object {[double]$_.terrainWeight-gt.5-and[double]$_.terrainGrade-lt-.05}).Count;$row.stairsUp=$up;$row.stairsDown=$dn
    if(!$up-or!$dn){throw "Stair gait not presented (up $up, down $dn)"};$row.checks.Add("Partner stair gait up ($up samples) and down ($dn samples)")}""")
rep("if($case-notin'kick','crouchheavy','note','mana'-and$low.Count-gt3){", "if($case-notin'kick','crouchheavy','note','mana','stairs'-and$low.Count-gt3){")
rep("scope='Visual coverage (sweep 1260): runs in 8 directions and sprint-to-slide, both source roles, product controller; fixture restored after every case.'",
    "scope='Locomotion completion coverage (1318, #11): walks and crouch walks in 8 directions, sprint and diagonals, in-place turns by size, starts/stops and speed changes, stairs; both source roles, product controller, free camera; checked from the partner presentation state; fixture restored after every case.'")
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Record-Coverage-v1318.ps1').write_bytes(out.encode('utf-8'))
print('ok')
